create table public.playfeed_removed_games (game_url text primary key check (char_length(game_url) between 1 and 2200 and game_url ~ '^https://'), removed_by text not null, removed_at timestamptz not null default now()); alter table public.playfeed_removed_games enable row level security; revoke all on public.playfeed_removed_games from anon, authenticated; grant select(game_url) on public.playfeed_removed_games to anon, authenticated; grant all on public.playfeed_removed_games to service_role; create policy "read removed game URLs" on public.playfeed_removed_games for select to anon, authenticated using (true);
